-- supabase/migrations/0019_archive_photo_cleanup.sql
-- Requires 0015 and 0016. Applies to orders finalized after this migration.

CREATE OR REPLACE FUNCTION public.enforce_order_archiving()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE previous_code text; next_code text;
BEGIN
  -- Only FK-triggered removal of user references may update finalized archives.
  IF TG_OP = 'UPDATE' AND pg_trigger_depth() > 1 THEN
    IF (to_jsonb(NEW) - 'created_by' - 'assigned_designer_id' - 'updated_at' - 'version')
      = (to_jsonb(OLD) - 'created_by' - 'assigned_designer_id' - 'updated_at' - 'version')
      AND (NEW.created_by IS NULL OR NEW.created_by IS NOT DISTINCT FROM OLD.created_by)
      AND (NEW.assigned_designer_id IS NULL OR NEW.assigned_designer_id IS NOT DISTINCT FROM OLD.assigned_designer_id) THEN
      RETURN NEW;
    END IF;
  END IF;
  IF current_setting('printex.importing',true) = 'yes' THEN RETURN NEW; END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT code INTO previous_code FROM public.production_steps WHERE id = OLD.current_step_id;
    IF previous_code = 'ARCHIVE' THEN
      IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Preserve archived orders and reports';
      END IF;
      IF (to_jsonb(NEW) - 'archive_finalized_at' - 'updated_at' - 'version')
         IS DISTINCT FROM (to_jsonb(OLD) - 'archive_finalized_at' - 'updated_at' - 'version') THEN
        RAISE EXCEPTION 'Archived order data is read-only';
      END IF;
      IF OLD.archive_finalized_at IS NOT NULL THEN
        RETURN OLD; -- repeated clicks cannot change the original report date
      END IF;
      IF NEW.archive_finalized_at IS NOT NULL THEN
        IF OLD.archived_at IS NULL OR OLD.delivery_method IS NULL THEN
          RAISE EXCEPTION 'Delivery confirmation is required before finalization';
        END IF;
        NEW.archive_finalized_at := statement_timestamp();
        NEW.photo_path := NULL; -- Release the photo only when leaving the board for reports.
      END IF;
      RETURN NEW;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.archive_finalized_at IS NOT NULL THEN
    RAISE EXCEPTION 'Move to the archive board before finalizing';
  END IF;
  SELECT code INTO next_code FROM public.production_steps WHERE id = NEW.current_step_id;
  IF next_code = 'ARCHIVE' THEN
    IF TG_OP = 'INSERT' OR previous_code IS DISTINCT FROM 'DONE' THEN
      RAISE EXCEPTION 'Only Done orders can be archived';
    END IF;
    IF NEW.delivery_method IS NULL OR NEW.delivery_method NOT IN ('pickup', 'delivery') THEN
      RAISE EXCEPTION 'Confirm pickup or delivery before archiving';
    END IF;
    NEW.archived_at := statement_timestamp();
    NEW.order_state := 'completed';
  ELSIF NEW.archived_at IS NOT NULL OR NEW.delivery_method IS NOT NULL THEN
    RAISE EXCEPTION 'Delivery metadata is only valid for archived orders';
  END IF;
  RETURN NEW;
END;
$$;

-- UPDATE OF photo_path would miss a path cleared inside a BEFORE trigger.
DROP TRIGGER IF EXISTS orders_queue_old_photo ON public.orders;
CREATE TRIGGER orders_queue_old_photo AFTER DELETE OR UPDATE ON public.orders
FOR EACH ROW EXECUTE FUNCTION public.printex_queue_old_photo();

-- supabase/migrations/0020_optional_customer_phone.sql
-- Optional customer WhatsApp. Preserves existing numbers when omitted by older clients.

CREATE OR REPLACE FUNCTION public.printex_mutate_order(p_action text, p_order_id uuid, p_expected_version bigint, p_data jsonb DEFAULT '{}')
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE o public.orders; customer_uuid uuid; stage_uuid uuid; result_id uuid; actor_role text; source_code text;
BEGIN
  -- Lock the authenticated profile until commit, including against concurrent role changes.
  SELECT p.role INTO actor_role FROM public.profiles p
    WHERE p.id=auth.uid() AND p.is_active AND p.role IN ('owner','admin','operator') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('create','edit','move','delete','archive','finish') THEN RAISE EXCEPTION 'Aksi tidak valid'; END IF;
  IF actor_role='operator' AND p_action<>'move' THEN
    RAISE EXCEPTION 'Operator tidak dapat menambah, mengedit, menghapus, atau mengarsipkan order' USING ERRCODE='42501';
  END IF;
  IF p_action IN ('create','edit') THEN
    IF length(trim(p_data->>'customerPhone')) > 30 THEN
      RAISE EXCEPTION 'Nomor WhatsApp maksimal 30 karakter';
    END IF;
    IF nullif(trim(p_data->>'customerName'),'') IS NULL OR length(p_data->>'customerName') > 200
       OR (p_data->>'productionType') NOT IN ('Sublim','DTF','Umbul-umbul','Batik','Jersey')
       OR p_data->>'productionType' IS NULL OR (p_data->>'meter')::numeric < 0
       OR (p_data->>'meter') IS NULL OR (p_data->>'customerType') NOT IN ('regular','priority')
       OR p_data->>'customerType' IS NULL OR nullif(p_data->>'orderDate','') IS NULL OR nullif(p_data->>'dueDate','') IS NULL THEN
      RAISE EXCEPTION 'Data order tidak lengkap atau tidak valid';
    END IF;
  END IF;
  IF p_action = 'create' THEN
    -- Client-generated UUID makes retry after a lost response idempotent.
    PERFORM pg_advisory_xact_lock(hashtextextended(p_order_id::text,0));
    IF EXISTS(SELECT 1 FROM public.orders WHERE id=p_order_id) THEN RETURN p_order_id; END IF;
    INSERT INTO public.customers(name,phone) VALUES(trim(p_data->>'customerName'),nullif(trim(p_data->>'customerPhone'),'')) RETURNING id INTO customer_uuid;
    INSERT INTO public.orders(id,spk_code,customer_id,production_type,meter,customer_type,order_date,due_at,notes,created_by)
    VALUES(p_order_id,'SPK-'||nextval('public.printex_spk_seq'),customer_uuid,p_data->>'productionType',
      (p_data->>'meter')::numeric,p_data->>'customerType',(p_data->>'orderDate')::date,(p_data->>'dueDate')::date,
      COALESCE(p_data->>'notes',''),auth.uid()) RETURNING id INTO result_id;
    RETURN result_id;
  END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order sudah dihapus atau tidak ditemukan'; END IF;
  IF actor_role='operator' THEN
    SELECT code INTO source_code FROM public.production_steps WHERE id=o.current_step_id;
    IF source_code IS NULL OR source_code NOT IN ('DESIGN_DONE','PRINTING','PRESS','DONE')
      OR COALESCE(p_data->>'code','') NOT IN ('DESIGN_DONE','PRINTING','PRESS','DONE') THEN
      RAISE EXCEPTION 'Operator hanya dapat memindahkan order antara Menunggu Pembayaran, Sublim, Press, dan Order Selesai' USING ERRCODE='42501';
    END IF;
  END IF;
  IF p_action='finish' AND o.archive_finalized_at IS NOT NULL THEN RETURN o.id; END IF;
  IF o.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'Order sudah diubah perangkat lain. Muat ulang dan coba lagi.' USING ERRCODE='40001'; END IF;
  CASE p_action
  WHEN 'edit' THEN
    IF nullif(trim(p_data->>'spkCode'),'') IS NULL THEN RAISE EXCEPTION 'Kode SPK wajib diisi'; END IF;
    UPDATE public.customers SET name=trim(p_data->>'customerName'),phone=CASE WHEN p_data ? 'customerPhone' THEN nullif(trim(p_data->>'customerPhone'),'') ELSE phone END,updated_at=statement_timestamp() WHERE id=o.customer_id;
    UPDATE public.orders SET spk_code=trim(p_data->>'spkCode'),production_type=p_data->>'productionType',meter=(p_data->>'meter')::numeric,
      customer_type=p_data->>'customerType',order_date=(p_data->>'orderDate')::date,due_at=(p_data->>'dueDate')::date,notes=COALESCE(p_data->>'notes','') WHERE id=o.id;
  WHEN 'move' THEN
    IF p_data->>'code' = 'ARCHIVE' THEN RAISE EXCEPTION 'Konfirmasi penyerahan sebelum arsip'; END IF;
    SELECT id INTO STRICT stage_uuid FROM public.production_steps WHERE code=p_data->>'code';
    UPDATE public.orders SET current_step_id=stage_uuid WHERE id=o.id;
  WHEN 'archive' THEN
    SELECT id INTO STRICT stage_uuid FROM public.production_steps WHERE code='ARCHIVE';
    UPDATE public.orders SET current_step_id=stage_uuid,delivery_method=p_data->>'deliveryMethod' WHERE id=o.id;
  WHEN 'finish' THEN
    UPDATE public.orders SET archive_finalized_at=statement_timestamp() WHERE id=o.id;
  WHEN 'delete' THEN
    DELETE FROM public.orders WHERE id=o.id;
  END CASE;
  RETURN o.id;
END $$;

-- supabase/migrations/0021_incremental_sync.sql
-- Transactional change cursor. No business row contents are stored here.

CREATE TABLE IF NOT EXISTS public.printex_sync_clock (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), revision bigint NOT NULL DEFAULT 0
);
INSERT INTO public.printex_sync_clock(singleton) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.printex_row_changes (
 table_name text NOT NULL, row_id uuid NOT NULL, branch_key text NOT NULL DEFAULT '',
 revision bigint NOT NULL, deleted boolean NOT NULL,
 PRIMARY KEY(table_name,row_id,branch_key)
);
CREATE INDEX IF NOT EXISTS printex_changes_revision ON public.printex_row_changes(revision);
ALTER TABLE public.printex_sync_clock ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.printex_row_changes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.printex_sync_clock,public.printex_row_changes FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.printex_record_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rev bigint; item jsonb; prior jsonb;
BEGIN
 -- The row lock is held until commit: cursors cannot skip a late-committing transaction.
 UPDATE public.printex_sync_clock SET revision=revision+1 WHERE singleton RETURNING revision INTO rev;
 item := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF TG_OP='UPDATE' THEN
  prior := to_jsonb(OLD);
  IF prior->>'branch_id' IS DISTINCT FROM item->>'branch_id' THEN
   INSERT INTO public.printex_row_changes VALUES(TG_TABLE_NAME,(prior->>'id')::uuid,coalesce(prior->>'branch_id',''),rev,true)
   ON CONFLICT(table_name,row_id,branch_key) DO UPDATE SET revision=EXCLUDED.revision,deleted=true;
  END IF;
 END IF;
 INSERT INTO public.printex_row_changes VALUES(TG_TABLE_NAME,(item->>'id')::uuid,coalesce(item->>'branch_id',''),rev,TG_OP='DELETE')
 ON CONFLICT(table_name,row_id,branch_key) DO UPDATE SET revision=EXCLUDED.revision,deleted=EXCLUDED.deleted;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.printex_record_change() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['orders','customers','production_steps','process_history'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS printex_track_change ON public.%I',t);
  EXECUTE format('CREATE TRIGGER printex_track_change AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.printex_record_change()',t);
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.printex_sync_changes(p_after bigint DEFAULT NULL,p_branch uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE permitted boolean; branch_mode boolean; result jsonb;
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
 branch_mode := to_regclass('public.branches') IS NOT NULL;
 IF branch_mode THEN
  IF p_branch IS NULL THEN EXECUTE 'SELECT public.printex_central_owner()' INTO permitted;
  ELSE EXECUTE 'SELECT public.printex_branch_access($1)' INTO permitted USING p_branch; END IF;
  IF NOT permitted THEN RAISE EXCEPTION 'Cabang tidak dapat diakses' USING ERRCODE='42501'; END IF;
 END IF;
 -- Clock and changes are read in ONE statement/snapshot. Return only IDs, never row contents.
 WITH delta AS (
  SELECT d.table_name,d.row_id FROM public.printex_row_changes d
  WHERE p_after IS NOT NULL AND d.revision>p_after
   AND (NOT branch_mode OR p_branch IS NULL OR d.branch_key=p_branch::text OR d.table_name='production_steps')
  LIMIT 2001
 ), summary AS (SELECT count(*) AS n FROM delta)
 SELECT jsonb_build_object('cursor',c.revision::text,'reset',summary.n>2000,'changes',
  CASE WHEN p_after IS NULL OR summary.n>2000 THEN '[]'::jsonb
  ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('table',d.table_name,'id',d.row_id)) FROM delta d),'[]'::jsonb) END)
 INTO result FROM public.printex_sync_clock c CROSS JOIN summary WHERE singleton;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.printex_sync_changes(bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.printex_sync_changes(bigint,uuid) TO authenticated;

-- supabase/migrations/0022_paper_width.sql
-- Apply after existing order migrations; supports single-branch and branch RPCs.

ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS paper_width numeric;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.orders'::regclass AND conname='orders_paper_width_check') THEN
  ALTER TABLE public.orders ADD CONSTRAINT orders_paper_width_check CHECK(paper_width IS NULL OR (production_type='Sublim' AND paper_width IN (1.2,1.6,1.8)));
 END IF;
END $$;
DO $migration$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.printex_mutate_order(text,uuid,bigint,jsonb)'::regprocedure) INTO definition;
 IF position('paperWidth' IN definition)=0 THEN
  IF position('production_type,meter,customer_type' IN definition)=0 OR position('meter=(p_data->>''meter'')::numeric,' IN definition)=0 THEN
   RAISE EXCEPTION 'Versi RPC tidak dikenali. Jalankan migrasi order sebelumnya.';
  END IF;
  definition := replace(definition, 'IF p_action IN (''create'',''edit'') THEN',
   'IF p_action IN (''create'',''edit'') THEN
    IF p_data ? ''paperWidth'' AND p_data->>''paperWidth'' IS NOT NULL AND
      ((p_data->>''paperWidth'') NOT IN (''1.2'',''1.6'',''1.8'') OR p_data->>''productionType'' <> ''Sublim'') THEN
      RAISE EXCEPTION ''Lebar kertas hanya untuk Sublim: pilih 1,2, 1,6, atau 1,8 meter'';
    END IF;');
  definition := replace(definition,'production_type,meter,customer_type','production_type,meter,paper_width,customer_type');
  definition := replace(definition,'(p_data->>''meter'')::numeric,p_data->>''customerType''','(p_data->>''meter'')::numeric,(p_data->>''paperWidth'')::numeric,p_data->>''customerType''');
  definition := replace(definition,'meter=(p_data->>''meter'')::numeric,',
   'meter=(p_data->>''meter'')::numeric,paper_width=CASE WHEN p_data->>''productionType''<>''Sublim'' THEN NULL WHEN p_data ? ''paperWidth'' THEN (p_data->>''paperWidth'')::numeric ELSE o.paper_width END,');
  EXECUTE definition;
 END IF;
END $migration$;

-- supabase/migrations/0023_non_dtf_paper_width.sql
-- All non-DTF production uses sublimation paper. Run after paper width migration.

ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_paper_width_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_paper_width_check
 CHECK(paper_width IS NULL OR (production_type='DTF' AND paper_width=0.6) OR (production_type<>'DTF' AND paper_width IN (1.2,1.6,1.8)));
DO $migration$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.printex_mutate_order(text,uuid,bigint,jsonb)'::regprocedure) INTO definition;
 IF position('paperWidth' IN definition)=0 THEN RAISE EXCEPTION 'Jalankan migrasi lebar kertas sebelumnya terlebih dahulu.'; END IF;
 definition := replace(definition, 'p_data->>''productionType'' <> ''Sublim''', 'p_data->>''productionType'' = ''DTF''');
 definition := replace(definition, 'p_data->>''productionType''<>''Sublim''', 'p_data->>''productionType''=''DTF''');
 definition := replace(definition, 'Lebar kertas hanya untuk Sublim:', 'Lebar kertas untuk semua produksi selain DTF:');
 EXECUTE definition;
END $migration$;

-- supabase/migrations/0024_dtf_paper_width.sql
-- DTF uses 0.6 m automatically; other production uses 1.2 / 1.6 / 1.8 m.

ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_paper_width_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_paper_width_check
 CHECK(paper_width IS NULL OR (production_type='DTF' AND paper_width=0.6) OR (production_type<>'DTF' AND paper_width IN (1.2,1.6,1.8)));
DO $migration$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.printex_mutate_order(text,uuid,bigint,jsonb)'::regprocedure) INTO definition;
 IF position('paperWidth' IN definition)=0 THEN RAISE EXCEPTION 'Jalankan migrasi lebar kertas sebelumnya terlebih dahulu.'; END IF;
 IF position('-- automatic DTF paper' IN definition)=0 THEN
  definition := replace(definition, 'IF p_action IN (''create'',''edit'') THEN',
   'IF p_action IN (''create'',''edit'') THEN
    -- automatic DTF paper
    IF p_data->>''productionType'' = ''DTF'' THEN
      p_data := jsonb_set(p_data, ''{paperWidth}'', ''"0.6"''::jsonb);
    END IF;');
 END IF;
 definition := replace(definition,
  '((p_data->>''paperWidth'') NOT IN (''1.2'',''1.6'',''1.8'') OR p_data->>''productionType'' = ''DTF'')',
  '(p_data->>''productionType'' <> ''DTF'' AND (p_data->>''paperWidth'') NOT IN (''1.2'',''1.6'',''1.8''))');
 definition := replace(definition, 'WHEN p_data->>''productionType''=''DTF'' THEN NULL', 'WHEN p_data->>''productionType''=''DTF'' THEN 0.6');
 IF position('ELSE CASE WHEN o.paper_width=0.6' IN definition)=0 THEN
 definition := replace(definition, 'ELSE o.paper_width END', 'ELSE CASE WHEN o.paper_width=0.6 THEN NULL ELSE o.paper_width END END');
 END IF;
 EXECUTE definition;
END $migration$;

-- supabase/migrations/0025_scoped_snapshot.sql
-- Load active production plus only the orders needed by the selected period.
-- Keep each selected order's complete history so revisits and original milestones
-- retain their existing reporting semantics. RLS applies to every source table.

CREATE INDEX IF NOT EXISTS orders_finalized_at_scope ON public.orders(archive_finalized_at);
CREATE INDEX IF NOT EXISTS orders_order_date_scope ON public.orders(order_date);
CREATE INDEX IF NOT EXISTS process_history_scope_time ON public.process_history(occurred_at,order_identity);
CREATE INDEX IF NOT EXISTS process_history_scope_identity ON public.process_history(order_identity);

DROP FUNCTION IF EXISTS public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb);
DROP FUNCTION IF EXISTS public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb,uuid,boolean,text[]);
CREATE FUNCTION public.printex_scoped_snapshot(
 p_start date, p_end date, p_branch uuid DEFAULT NULL,
 p_order uuid DEFAULT NULL, p_changes jsonb DEFAULT NULL,
 p_history_after uuid DEFAULT NULL,p_history_only boolean DEFAULT false,p_history_ids text[] DEFAULT NULL
) RETURNS json LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE branch_mode boolean; result json; branch_order text; branch_history text; history_branch_field text; history_branch_column text;
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 THEN
  RAISE EXCEPTION 'Rentang data tidak valid';
 END IF;
 branch_mode := to_regclass('public.branches') IS NOT NULL;
 branch_order := CASE WHEN branch_mode THEN ' AND ($3 IS NULL OR o.branch_id=$3)' ELSE '' END;
 branch_history := CASE WHEN branch_mode THEN ' AND ($3 IS NULL OR h.branch_id=$3)' ELSE '' END;
 history_branch_field := CASE WHEN branch_mode THEN ', ''branch_id'',h.branch_id' ELSE '' END;
 history_branch_column := CASE WHEN branch_mode THEN ',h.branch_id' ELSE '' END;
 EXECUTE '
 WITH selected_identity AS MATERIALIZED (
  SELECT unnest($8::text[]) AS identity WHERE $8 IS NOT NULL
  UNION
  SELECT o.id::text AS identity FROM public.orders o WHERE $8 IS NULL AND
   (o.archive_finalized_at IS NULL OR o.order_date BETWEEN $1 AND $2
    OR o.archive_finalized_at >= ($1::timestamp AT TIME ZONE ''Asia/Jakarta'')
       AND o.archive_finalized_at < (($2+1)::timestamp AT TIME ZONE ''Asia/Jakarta'')
    OR o.id=$4)' || branch_order || '
  UNION
  SELECT h.order_identity FROM public.process_history h WHERE $8 IS NULL AND
   h.occurred_at >= ($1::timestamp AT TIME ZONE ''Asia/Jakarta'')
   AND h.occurred_at < (($2+1)::timestamp AT TIME ZONE ''Asia/Jakarta'')' || branch_history || '
 ), selected_orders AS MATERIALIZED (
  SELECT o.id,o.customer_id FROM public.orders o JOIN selected_identity i ON i.identity=o.id::text
  WHERE true' || branch_order || '
 ), changed AS MATERIALIZED (
  SELECT item->>''table'' AS table_name,item->>''id'' AS id
  FROM jsonb_array_elements(coalesce($5,''[]''::jsonb)) item
 ), history_page AS MATERIALIZED (
  SELECT h.id,h.order_identity,h.spk_code,h.step_id,h.event_kind,h.occurred_at,h.actor_name,h.customer_name' || history_branch_column || '
  FROM public.process_history h JOIN selected_identity i ON i.identity=h.order_identity
  WHERE ($6 IS NULL OR h.id>$6)' || branch_history || '
   AND ($5 IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name=''process_history'' AND c.id=h.id::text))
  ORDER BY h.id LIMIT 5001
 ), history_rows AS MATERIALIZED (SELECT * FROM history_page ORDER BY id LIMIT 5000)
 SELECT json_build_object(
  ''orders'',CASE WHEN $7 THEN ''[]''::json ELSE coalesce((SELECT json_agg(row_to_json(o)) FROM public.orders o JOIN selected_orders s ON s.id=o.id
   WHERE $5 IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name=''orders'' AND c.id=o.id::text)),''[]''::json) END,
  ''customers'',CASE WHEN $7 THEN ''[]''::json ELSE coalesce((SELECT json_agg(json_build_object(''id'',t.id,''name'',t.name,''phone'',t.phone)) FROM public.customers t
   WHERE EXISTS(SELECT 1 FROM selected_orders o WHERE o.customer_id=t.id)
   AND ($5 IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name=''customers'' AND c.id=t.id::text))),''[]''::json) END,
  ''production_steps'',CASE WHEN $7 THEN ''[]''::json ELSE coalesce((SELECT json_agg(json_build_object(''id'',t.id,''code'',t.code)) FROM public.production_steps t
   WHERE $5 IS NULL OR EXISTS(SELECT 1 FROM changed c WHERE c.table_name=''production_steps'' AND c.id=t.id::text)),''[]''::json) END,
  ''process_history'',coalesce((SELECT json_agg(json_build_object(
   ''id'',h.id,''order_identity'',h.order_identity,''spk_code'',h.spk_code,''step_id'',h.step_id,
   ''event_kind'',h.event_kind,''occurred_at'',h.occurred_at,''actor_name'',h.actor_name,
   ''customer_name'',h.customer_name' || history_branch_field || ')) FROM history_rows h),''[]''::json),
  ''history_more'',(SELECT count(*)>5000 FROM history_page),
  ''history_cursor'',(SELECT id FROM history_rows ORDER BY id DESC LIMIT 1),
  ''identities'',CASE WHEN $7 THEN ''[]''::json ELSE coalesce((SELECT json_agg(identity) FROM selected_identity),''[]''::json) END
 )' INTO result USING p_start,p_end,p_branch,p_order,p_changes,p_history_after,p_history_only,p_history_ids;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb,uuid,boolean,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb,uuid,boolean,text[]) TO authenticated;

-- supabase/migrations/0026_cached_branch_reads.sql
-- Evaluate the authorized branch set once per read statement, instead of
-- looking up the same profile and branch for each history row.

DO $migration$
DECLARE t text;
BEGIN
 IF to_regclass('public.branches') IS NULL THEN RETURN; END IF;
 EXECUTE $function$
  CREATE OR REPLACE FUNCTION public.printex_read_branches() RETURNS SETOF uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $body$
   SELECT b.id FROM public.branches b JOIN public.profiles p ON p.id=(SELECT auth.uid())
   WHERE b.is_active AND p.is_active
    AND (p.role='central_owner' OR (p.branch_id=b.id AND p.role IN ('owner','admin','operator')))
  $body$
 $function$;
 REVOKE ALL ON FUNCTION public.printex_read_branches() FROM PUBLIC,anon;
 GRANT EXECUTE ON FUNCTION public.printex_read_branches() TO authenticated;
 ALTER POLICY branches_read ON public.branches USING(id IN (SELECT public.printex_read_branches()));
 FOREACH t IN ARRAY ARRAY['orders','customers','process_history'] LOOP
  EXECUTE format('ALTER POLICY branch_read ON public.%I USING(branch_id IN (SELECT public.printex_read_branches()))',t);
 END LOOP;
END $migration$;

-- supabase/migrations/0027_compact_transitions.sql
-- One row per transition; retain the destination for accurate timing/revisions.

ALTER TABLE public.process_history ADD COLUMN IF NOT EXISTS next_step_id uuid REFERENCES public.production_steps(id);
ALTER TABLE public.process_history ADD COLUMN IF NOT EXISTS next_event_id uuid;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_delivery_method_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_delivery_method_check CHECK(delivery_method IN ('pickup','delivery','received'));

CREATE OR REPLACE FUNCTION public.capture_process_history()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_sequence integer; next_sequence integer; employee_name text; customer text;
BEGIN
 IF current_setting('printex.importing',true)='yes' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.current_step_id IS NOT DISTINCT FROM NEW.current_step_id THEN RETURN NEW; END IF;
 IF NEW.current_step_id IS NULL THEN RAISE EXCEPTION 'An existing production stage cannot be cleared'; END IF;
 SELECT sequence INTO STRICT next_sequence FROM public.production_steps WHERE id=NEW.current_step_id;
 SELECT full_name INTO employee_name FROM public.profiles WHERE id=auth.uid();
 SELECT name INTO customer FROM public.customers WHERE id=NEW.customer_id;
 IF TG_OP='UPDATE' AND OLD.current_step_id IS NOT NULL THEN
  SELECT sequence INTO STRICT previous_sequence FROM public.production_steps WHERE id=OLD.current_step_id;
  INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,actor_id,actor_name,assigned_employee_id,customer_name,next_step_id,next_event_id,occurred_at)
  VALUES(NEW.id,NEW.spk_code,OLD.current_step_id,CASE WHEN next_sequence>previous_sequence THEN 'completed' ELSE 'returned' END,
   auth.uid(),employee_name,OLD.assigned_designer_id,coalesce(customer,''),NEW.current_step_id,gen_random_uuid(),statement_timestamp());
 ELSE
  -- One initial anchor per order, rather than an entry at every stage.
  INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,actor_id,actor_name,assigned_employee_id,customer_name,occurred_at)
  VALUES(NEW.id,NEW.spk_code,NEW.current_step_id,'entered',auth.uid(),employee_name,NEW.assigned_designer_id,coalesce(customer,''),statement_timestamp());
 END IF;
 RETURN NEW;
END $$;

-- Preserve existing archive protections and branch retirement behavior.
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.enforce_order_archiving()'::regprocedure) INTO definition;
 definition:=replace(definition,'''pickup'', ''delivery''','''pickup'', ''delivery'', ''received''');
 definition:=replace(definition,'NEW.archived_at := statement_timestamp();',
  'NEW.archived_at := statement_timestamp(); IF NEW.delivery_method = ''received'' THEN NEW.archive_finalized_at := NEW.archived_at; NEW.photo_path := NULL; END IF;');
 EXECUTE definition;
END $$;

-- Add compact metadata to the scoped response without expanding it on the server.
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb,uuid,boolean,text[])'::regprocedure) INTO definition;
 IF position('h.next_step_id' IN definition)=0 THEN
  definition:=replace(definition,'h.actor_name,h.customer_name','h.actor_name,h.customer_name,h.next_step_id,h.next_event_id');
  definition:=replace(definition,'''customer_name'''',h.customer_name','''customer_name'''',h.customer_name,''''next_step_id'''',h.next_step_id,''''next_event_id'''',h.next_event_id');
  EXECUTE definition;
 END IF;
END $$;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0028_skip_archive_process_reads.sql
-- Receipt is reported from orders.archive_finalized_at, not a seventh process.
-- Preserve stored history; omit unused archive-stage rows from dashboard reads.

DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.printex_scoped_snapshot(date,date,uuid,uuid,jsonb,uuid,boolean,text[])'::regprocedure) INTO definition;
 IF position('skip_archive_process' IN definition)=0 THEN
  definition:=replace(definition,'WHERE ($6 IS NULL OR h.id>$6)',
   'WHERE ($6 IS NULL OR h.id>$6) AND h.step_id NOT IN (SELECT id FROM public.production_steps WHERE code=''''ARCHIVE'''') /* skip_archive_process */');
  EXECUTE definition;
 END IF;
END $$;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0029_manual_spk_on_create.sql
-- Use the manually entered SPK on create; preserve retries and legacy clients.

DO $$ DECLARE definition text; generated text := '''SPK-''||nextval(''public.printex_spk_seq'')'; BEGIN
 SELECT pg_get_functiondef('public.printex_mutate_order(text,uuid,bigint,jsonb)'::regprocedure) INTO definition;
 IF position('manual_spk_on_create' IN definition)=0 THEN
  IF position(generated IN definition)=0 THEN RAISE EXCEPTION 'SPK generator not recognized; refusing function replacement'; END IF;
  definition:=replace(definition,generated,
   'coalesce(nullif(trim(p_data->>''spkCode''),''''),'||generated||') /* manual_spk_on_create */');
  definition:=replace(definition,'IF p_action = ''create'' THEN',
   'IF p_action = ''create'' THEN IF p_data ? ''spkCode'' AND nullif(trim(p_data->>''spkCode''),'''') IS NULL THEN RAISE EXCEPTION ''Kode SPK wajib diisi''; END IF;');
  EXECUTE definition;
 END IF;
END $$;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0030_history_without_actors.sql
-- Preserve the history API shape; do not store the person performing a move.

CREATE OR REPLACE FUNCTION public.capture_process_history()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_sequence integer; next_sequence integer; customer text;
BEGIN
 IF current_setting('printex.importing',true)='yes' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.current_step_id IS NOT DISTINCT FROM NEW.current_step_id THEN RETURN NEW; END IF;
 IF NEW.current_step_id IS NULL THEN RAISE EXCEPTION 'An existing production stage cannot be cleared'; END IF;
 SELECT sequence INTO STRICT next_sequence FROM public.production_steps WHERE id=NEW.current_step_id;
 SELECT name INTO customer FROM public.customers WHERE id=NEW.customer_id;
 IF TG_OP='UPDATE' AND OLD.current_step_id IS NOT NULL THEN
  SELECT sequence INTO STRICT previous_sequence FROM public.production_steps WHERE id=OLD.current_step_id;
  INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,customer_name,next_step_id,next_event_id,occurred_at)
  VALUES(NEW.id,NEW.spk_code,OLD.current_step_id,CASE WHEN next_sequence>previous_sequence THEN 'completed' ELSE 'returned' END,
   coalesce(customer,''),NEW.current_step_id,gen_random_uuid(),statement_timestamp());
 ELSE
  INSERT INTO public.process_history(order_id,spk_code,step_id,event_kind,customer_name,occurred_at)
  VALUES(NEW.id,NEW.spk_code,NEW.current_step_id,'entered',coalesce(customer,''),statement_timestamp());
 END IF;
 RETURN NEW;
END $$;

-- Imports also pass through this guard. Compatibility columns stay NULL.
CREATE OR REPLACE FUNCTION public.printex_history_no_actor() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 NEW.actor_id:=NULL; NEW.actor_name:=NULL; NEW.assigned_employee_id:=NULL;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.printex_history_no_actor() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS history_no_actor ON public.process_history;
CREATE TRIGGER history_no_actor BEFORE INSERT OR UPDATE ON public.process_history
FOR EACH ROW EXECUTE FUNCTION public.printex_history_no_actor();
UPDATE public.process_history SET actor_id=NULL,actor_name=NULL,assigned_employee_id=NULL
WHERE actor_id IS NOT NULL OR actor_name IS NOT NULL OR assigned_employee_id IS NOT NULL;
DROP INDEX IF EXISTS public.process_history_actor_time;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0031_daily_reports.sql
-- Saved daily reports: per-order contributions and daily totals, refreshed through a queue.
-- Derived data only; business rows and histories are never changed. Safe to rerun.
CREATE TABLE IF NOT EXISTS public.report_daily_summaries (
 report_date date NOT NULL, metric text NOT NULL, dimension text NOT NULL DEFAULT '',
 order_count bigint NOT NULL DEFAULT 0, meter numeric NOT NULL DEFAULT 0,
 milliseconds numeric NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(report_date,metric,dimension)
);
CREATE TABLE IF NOT EXISTS public.report_contributions (
 order_id uuid NOT NULL, report_date date NOT NULL, metric text NOT NULL, dimension text NOT NULL DEFAULT '',
 meter numeric NOT NULL DEFAULT 0, milliseconds numeric NOT NULL DEFAULT 0,
 data jsonb NOT NULL DEFAULT '{}',
 PRIMARY KEY(order_id,report_date,metric,dimension)
);
CREATE INDEX IF NOT EXISTS report_contributions_period ON public.report_contributions(metric,dimension,report_date,order_id);
CREATE INDEX IF NOT EXISTS report_details_page ON public.report_contributions(metric,dimension,report_date DESC,order_id);
CREATE TABLE IF NOT EXISTS public.report_refresh_queue (
 order_id uuid PRIMARY KEY, queued_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS report_queue_oldest ON public.report_refresh_queue(queued_at,order_id);
-- The order snapshot is stored once per order instead of in every contribution.
CREATE TABLE IF NOT EXISTS public.report_order_payloads (
 order_id uuid PRIMARY KEY, data jsonb NOT NULL
);
ALTER TABLE public.report_daily_summaries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_contributions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_refresh_queue ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.report_order_payloads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.report_daily_summaries,public.report_contributions,public.report_refresh_queue,public.report_order_payloads FROM PUBLIC,anon,authenticated;

-- Daily totals follow every contribution change.
CREATE OR REPLACE FUNCTION public.printex_report_delta() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.report_contributions; sign integer; BEGIN
 IF TG_OP='UPDATE' THEN
  UPDATE public.report_daily_summaries SET order_count=order_count-CASE WHEN OLD.metric='flow' THEN (OLD.data->>'visits')::bigint ELSE 1 END,meter=meter-OLD.meter,milliseconds=milliseconds-OLD.milliseconds
  WHERE report_date=OLD.report_date AND metric=OLD.metric AND dimension=OLD.dimension;
 END IF;
 IF TG_OP='DELETE' THEN r:=OLD; sign:=-1; ELSE r:=NEW; sign:=1; END IF;
 INSERT INTO public.report_daily_summaries(report_date,metric,dimension,order_count,meter,milliseconds)
 VALUES(r.report_date,r.metric,r.dimension,sign*CASE WHEN r.metric='flow' THEN (r.data->>'visits')::bigint ELSE 1 END,sign*r.meter,sign*r.milliseconds)
 ON CONFLICT(report_date,metric,dimension) DO UPDATE SET
 order_count=public.report_daily_summaries.order_count+excluded.order_count,
 meter=public.report_daily_summaries.meter+excluded.meter,
 milliseconds=public.report_daily_summaries.milliseconds+excluded.milliseconds,updated_at=now();
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS report_contribution_delta ON public.report_contributions;
CREATE TRIGGER report_contribution_delta AFTER INSERT OR UPDATE OR DELETE ON public.report_contributions FOR EACH ROW EXECUTE FUNCTION public.printex_report_delta();

-- Keep the order snapshot in report_order_payloads; never store who moved an order.
CREATE OR REPLACE FUNCTION public.printex_compact_report_payload() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NEW.data ? 'order' AND NEW.data->'order'<>'null'::jsonb THEN
  INSERT INTO public.report_order_payloads(order_id,data) VALUES(NEW.order_id,NEW.data->'order')
  ON CONFLICT(order_id) DO UPDATE SET data=excluded.data WHERE public.report_order_payloads.data IS DISTINCT FROM excluded.data;
  NEW.data:=jsonb_set(NEW.data,'{order}','null'::jsonb);
 END IF;
 IF NEW.data ? 'event' THEN NEW.data:=jsonb_set(NEW.data,'{event,actorName}','null'::jsonb); END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS report_compact_payload ON public.report_contributions;
CREATE TRIGGER report_compact_payload BEFORE INSERT OR UPDATE ON public.report_contributions
FOR EACH ROW EXECUTE FUNCTION public.printex_compact_report_payload();

CREATE OR REPLACE VIEW public.printex_report_expanded AS
SELECT c.order_id,c.report_date,c.metric,c.dimension,c.meter,c.milliseconds,
 CASE WHEN c.data ? 'order' AND p.order_id IS NOT NULL THEN jsonb_set(c.data,'{order}',p.data) ELSE c.data END AS data
FROM public.report_contributions c LEFT JOIN public.report_order_payloads p ON p.order_id=c.order_id;
REVOKE ALL ON public.printex_report_expanded FROM PUBLIC,anon,authenticated;

-- Changed orders, histories and customer names are queued for a refresh.
CREATE OR REPLACE FUNCTION public.printex_queue_report() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid; identity text; BEGIN
 IF TG_TABLE_NAME='process_history' THEN
  identity:=CASE WHEN TG_OP='DELETE' THEN OLD.order_identity ELSE NEW.order_identity END;
  oid:=CASE WHEN identity ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN identity::uuid END;
 ELSE
  oid:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
 END IF;
 IF oid IS NOT NULL THEN
  INSERT INTO public.report_refresh_queue(order_id) VALUES(oid) ON CONFLICT(order_id) DO UPDATE SET queued_at=now();
 END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS orders_queue_report ON public.orders;
CREATE TRIGGER orders_queue_report AFTER INSERT OR UPDATE OR DELETE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.printex_queue_report();
DROP TRIGGER IF EXISTS history_queue_report ON public.process_history;
CREATE TRIGGER history_queue_report AFTER INSERT OR UPDATE OR DELETE ON public.process_history FOR EACH ROW EXECUTE FUNCTION public.printex_queue_report();

CREATE OR REPLACE FUNCTION public.printex_queue_customer_report() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NEW.name IS DISTINCT FROM OLD.name THEN
  INSERT INTO public.report_refresh_queue(order_id) SELECT id FROM public.orders WHERE customer_id=NEW.id
  ON CONFLICT(order_id) DO UPDATE SET queued_at=now();
 END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS customers_queue_report ON public.customers;
CREATE TRIGGER customers_queue_report AFTER UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION public.printex_queue_customer_report();

CREATE OR REPLACE FUNCTION public.printex_report_add(p_id uuid,p_day date,p_metric text,p_dimension text DEFAULT '',p_meter numeric DEFAULT 0,p_ms numeric DEFAULT 0,p_data jsonb DEFAULT '{}')
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 INSERT INTO public.report_contributions(order_id,report_date,metric,dimension,meter,milliseconds,data)
 VALUES(p_id,p_day,p_metric,p_dimension,p_meter,p_ms,p_data)
 ON CONFLICT DO NOTHING;
$$;

-- Rebuilds every contribution of one order from its row and complete history.
CREATE OR REPLACE FUNCTION public.printex_refresh_report_order(p_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; customer text; events jsonb; e jsonb; code text; kind text;
 stamp timestamptz; started timestamptz; completed timestamptz; last_stamp timestamptz; ending timestamptz;
 open_code text; open_at timestamptz; flow_code text; flow_at timestamptz;
 durations jsonb:='{}'; exits jsonb:='{}'; visited jsonb:='{}'; ms numeric; day date; dim text;
 payload jsonb; order_data jsonb; base jsonb; is_finished boolean; timing_code text;
BEGIN
 SELECT * INTO o FROM public.orders WHERE id=p_id;
 DELETE FROM public.report_contributions WHERE order_id=p_id;
 DELETE FROM public.report_order_payloads WHERE order_id=p_id;
 -- A deleted order keeps its process milestones as long as its history remains.
 IF o.id IS NULL AND NOT EXISTS(SELECT 1 FROM public.process_history WHERE order_identity=p_id::text) THEN RETURN; END IF;
 SELECT name INTO customer FROM public.customers WHERE id=o.customer_id;
 order_data:=jsonb_build_object('id',o.id,'spk_code',o.spk_code,'customer',jsonb_build_object('name',coalesce(customer,''),'phone',''),
  'production_type',o.production_type,'meter',coalesce(o.meter,0),'paper_width',o.paper_width,'customer_type',o.customer_type,
  'order_date',o.order_date,'due_at',o.due_at,'order_state',o.order_state,'photo_path',o.photo_path,
  'archive',CASE WHEN o.archived_at IS NULL THEN NULL ELSE jsonb_build_object('archivedAt',o.archived_at,'finalizedAt',o.archive_finalized_at,'deliveryMethod',o.delivery_method) END);
 SELECT coalesce(jsonb_agg(t.data ORDER BY t.stamp,(t.kind='entered')::integer,t.id),'[]') INTO events FROM (
  SELECT h.id,h.occurred_at AS stamp,h.event_kind AS kind,
   jsonb_build_object('id',h.id,'code',s.code,'kind',h.event_kind,'at',h.occurred_at,'actor',NULL,'customer',h.customer_name,'spk',h.spk_code) AS data
  FROM public.process_history h JOIN public.production_steps s ON s.id=h.step_id WHERE h.order_identity=p_id::text
  UNION ALL
  SELECT h.next_event_id,h.occurred_at,'entered',
   jsonb_build_object('id',h.next_event_id,'code',s.code,'kind','entered','at',h.occurred_at,'actor',NULL,'customer',h.customer_name,'spk',h.spk_code)
  FROM public.process_history h JOIN public.production_steps s ON s.id=h.next_step_id WHERE h.order_identity=p_id::text
 ) t;
 -- Original completion milestones: deduplicate before any date filtering.
 FOR e IN SELECT DISTINCT ON (value->>'code') value FROM jsonb_array_elements(events)
  WHERE value->>'kind'='completed' AND value->>'code' NOT IN ('DONE','ARCHIVE') ORDER BY value->>'code',(value->>'at')::timestamptz,value->>'id' LOOP
  code:=e->>'code'; stamp:=(e->>'at')::timestamptz; day:=(stamp AT TIME ZONE 'Asia/Jakarta')::date;
  base:=jsonb_build_object('id',e->>'id','orderId',p_id,'spkCode',e->>'spk','customerName',coalesce(e->>'customer',''),'kind','completed','orderExists',o.id IS NOT NULL,'occurredAt',stamp,'actorName',NULL);
  PERFORM public.printex_report_add(p_id,day,'process',code,0,0,jsonb_build_object('event',base));
  IF code='PRINTING' AND o.id IS NOT NULL THEN
   dim:=CASE WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE 'sublim' END;
   PERFORM public.printex_report_add(p_id,day,'output',dim,greatest(o.meter,0));
   dim:=CASE WHEN upper(trim(o.production_type))='DTF' THEN '0.6' WHEN o.paper_width IN (1.2,1.6,1.8) THEN trim(trailing '0' FROM o.paper_width::text) ELSE 'unknown' END;
   dim:=CASE WHEN dim IN ('1.2','1.6','1.8','0.6') THEN dim ELSE 'unknown' END;
   PERFORM public.printex_report_add(p_id,day,'paper',dim,greatest(o.meter,0));
  END IF;
 END LOOP;
 IF o.id IS NULL THEN RETURN; END IF;
 PERFORM public.printex_report_add(p_id,o.order_date,'intake','');
 IF o.order_state<>'cancelled' AND (o.order_state='completed' OR o.archive_finalized_at IS NOT NULL) THEN
  PERFORM public.printex_report_add(p_id,o.order_date,'intake_completed','');
 END IF;
 IF o.archive_finalized_at IS NOT NULL THEN
  day:=(o.archive_finalized_at AT TIME ZONE 'Asia/Jakarta')::date;
  PERFORM public.printex_report_add(p_id,day,'archive','',greatest(o.meter,0),0,jsonb_build_object('order',order_data));
  base:=jsonb_build_object('id','archive-completed-'||p_id,'orderId',p_id,'spkCode',o.spk_code,'customerName',coalesce(customer,''),'kind','completed','orderExists',true,'occurredAt',o.archive_finalized_at,'actorName',NULL);
  PERFORM public.printex_report_add(p_id,day,'process','DONE',0,0,jsonb_build_object('event',base));
 END IF;
 SELECT min((value->>'at')::timestamptz) FILTER(WHERE value->>'kind'='entered' AND value->>'code' IN ('DESIGN','DESIGN_DONE')),
  min((value->>'at')::timestamptz) FILTER(WHERE value->>'kind'='entered' AND value->>'code'='DONE'),max((value->>'at')::timestamptz)
 INTO started,completed,last_stamp FROM jsonb_array_elements(events);
 is_finished:=completed IS NOT NULL OR (SELECT production_steps.code IN ('DONE','ARCHIVE') FROM public.production_steps WHERE id=o.current_step_id);
 ending:=coalesce(completed,last_stamp);
 FOR e IN SELECT value FROM jsonb_array_elements(events) LOOP
  code:=e->>'code'; kind:=e->>'kind'; stamp:=(e->>'at')::timestamptz;
  -- Flow averages retain all actual visits; returns are not completions.
  IF flow_code IS NOT NULL AND (kind='entered' OR flow_code=code) AND NOT(kind='entered' AND flow_code=code) THEN
   IF kind='completed' OR (kind='entered' AND (SELECT sequence FROM public.production_steps WHERE production_steps.code=e->>'code')>(SELECT sequence FROM public.production_steps WHERE production_steps.code=flow_code)) THEN
    day:=(stamp AT TIME ZONE 'Asia/Jakarta')::date;
    INSERT INTO public.report_contributions(order_id,report_date,metric,dimension,milliseconds,data)
    VALUES(p_id,day,'flow',flow_code,greatest(extract(epoch FROM stamp-flow_at)*1000,0),jsonb_build_object('visits',1))
    ON CONFLICT(order_id,report_date,metric,dimension) DO UPDATE SET milliseconds=public.report_contributions.milliseconds+excluded.milliseconds,data=jsonb_build_object('visits',(public.report_contributions.data->>'visits')::integer+1);
   END IF;
   flow_code:=NULL;
  END IF;
  IF kind='entered' AND flow_code IS DISTINCT FROM code THEN flow_code:=code; flow_at:=stamp; END IF;
  IF started IS NULL OR stamp<started OR stamp>ending THEN CONTINUE; END IF;
  IF (kind<>'entered' AND open_code=code) OR (kind='entered' AND open_code IS NOT NULL AND open_code IS DISTINCT FROM code) THEN
   ms:=greatest(extract(epoch FROM least(stamp,ending)-open_at)*1000,0);
   durations:=jsonb_set(durations,ARRAY[open_code],to_jsonb(coalesce((durations->>open_code)::numeric,0)+ms));
   exits:=jsonb_set(exits,ARRAY[open_code],to_jsonb(least(stamp,ending))); open_code:=NULL;
  END IF;
  IF kind='entered' AND code IN ('DESIGN','DESIGN_DONE','PRINTING','PRESS') AND open_code IS DISTINCT FROM code THEN
   open_code:=code; open_at:=stamp; visited:=jsonb_set(visited,ARRAY[code],'true');
  END IF;
 END LOOP;
 IF open_code IS NOT NULL AND is_finished THEN
  durations:=jsonb_set(durations,ARRAY[open_code],to_jsonb(coalesce((durations->>open_code)::numeric,0)+greatest(extract(epoch FROM ending-open_at)*1000,0)));
  IF completed IS NOT NULL THEN exits:=jsonb_set(exits,ARRAY[open_code],to_jsonb(completed)); END IF;
 END IF;
 payload:=jsonb_build_object('order',order_data,'productionMilliseconds',CASE WHEN started IS NOT NULL AND completed IS NOT NULL THEN greatest(extract(epoch FROM completed-started)*1000,0) END);
 IF started IS NOT NULL AND completed IS NOT NULL THEN
  day:=(completed AT TIME ZONE 'Asia/Jakarta')::date;
  PERFORM public.printex_report_add(p_id,day,'production','',0,greatest(extract(epoch FROM completed-started)*1000,0),payload);
 END IF;
 FOREACH timing_code IN ARRAY ARRAY['DESIGN','DESIGN_DONE','PRINTING','PRESS'] LOOP
  IF visited ? timing_code AND exits ? timing_code AND NOT(coalesce(NOT is_finished AND open_code=timing_code,false)) THEN
   day:=((exits->>timing_code)::timestamptz AT TIME ZONE 'Asia/Jakarta')::date; ms:=coalesce((durations->>timing_code)::numeric,0);
   PERFORM public.printex_report_add(p_id,day,'timing',timing_code,0,ms,payload);
   IF timing_code IN ('PRINTING','PRESS') THEN
    dim:=CASE WHEN timing_code='PRESS' THEN 'press' WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE 'sublim' END;
    PERFORM public.printex_report_add(p_id,day,'productivity',dim||':'||CASE WHEN upper(trim(o.production_type))='DTF' THEN 'dtf' ELSE coalesce((o.paper_width::float8)::text,'unknown') END,greatest(o.meter,0),ms);
   END IF;
  END IF;
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.printex_refresh_report_queue(p_limit integer DEFAULT 100) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r record; refreshed integer:=0; BEGIN
 IF NOT pg_try_advisory_xact_lock(73621,1) THEN RETURN -1; END IF;
 FOR r IN SELECT order_id FROM public.report_refresh_queue ORDER BY queued_at,order_id LIMIT least(greatest(p_limit,1),500) FOR UPDATE SKIP LOCKED LOOP
  PERFORM public.printex_refresh_report_order(r.order_id);
  DELETE FROM public.report_refresh_queue WHERE order_id=r.order_id; refreshed:=refreshed+1;
 END LOOP;
 RETURN refreshed;
END $$;

-- Daily totals of a period; refreshes up to 100 queued orders first.
CREATE OR REPLACE FUNCTION public.printex_daily_report(p_start date,p_end date) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r record; pending boolean; result jsonb; BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 THEN RAISE EXCEPTION 'Rentang laporan tidak valid'; END IF;
 IF pg_try_advisory_xact_lock(73621,1) THEN
  FOR r IN SELECT order_id FROM public.report_refresh_queue ORDER BY queued_at,order_id LIMIT 100 FOR UPDATE SKIP LOCKED LOOP
   PERFORM public.printex_refresh_report_order(r.order_id); DELETE FROM public.report_refresh_queue WHERE order_id=r.order_id;
  END LOOP;
 END IF;
 SELECT exists(SELECT 1 FROM public.report_refresh_queue) INTO pending;
 SELECT coalesce(jsonb_agg(jsonb_build_object('day',report_date,'metric',metric,'dimension',dimension,'count',order_count,'meter',meter,'milliseconds',milliseconds) ORDER BY report_date,metric,dimension),'[]') INTO result
 FROM public.report_daily_summaries WHERE report_date BETWEEN p_start AND p_end AND order_count>0;
 RETURN jsonb_build_object('rows',result,'pending',pending,'asOf',now());
END $$;

-- Paged rows behind one daily total (archive, process, timing or production).
CREATE OR REPLACE FUNCTION public.printex_report_details(p_start date,p_end date,p_metric text,p_dimension text DEFAULT '',p_offset integer DEFAULT 0,p_limit integer DEFAULT 50,p_search text DEFAULT '') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb; total bigint; BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif' USING ERRCODE='42501'; END IF;
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>365 OR p_metric IS NULL OR p_metric NOT IN ('archive','process','timing','production') OR p_offset IS NULL OR p_offset<0 THEN RAISE EXCEPTION 'Filter laporan tidak valid'; END IF;
 SELECT count(*) INTO total FROM public.printex_report_expanded WHERE report_date BETWEEN p_start AND p_end AND metric=p_metric AND dimension=p_dimension
 AND (p_search='' OR position(lower(p_search) IN lower(coalesce(data->'order'->>'spk_code',data->'event'->>'spkCode','')||' '||coalesce(data->'order'->'customer'->>'name',data->'event'->>'customerName','')))>0);
 SELECT coalesce(jsonb_agg(t.data),'[]') INTO result FROM (SELECT data||jsonb_build_object('milliseconds',milliseconds,'day',report_date) AS data FROM public.printex_report_expanded
 WHERE report_date BETWEEN p_start AND p_end AND metric=p_metric AND dimension=p_dimension
 AND (p_search='' OR position(lower(p_search) IN lower(coalesce(data->'order'->>'spk_code',data->'event'->>'spkCode','')||' '||coalesce(data->'order'->'customer'->>'name',data->'event'->>'customerName','')))>0)
 ORDER BY report_date DESC,order_id LIMIT least(greatest(p_limit,1),200) OFFSET p_offset) t;
 RETURN jsonb_build_object('items',result,'total',total);
END $$;

REVOKE ALL ON FUNCTION public.printex_report_delta(),public.printex_compact_report_payload(),public.printex_queue_report(),public.printex_queue_customer_report(),
 public.printex_report_add(uuid,date,text,text,numeric,numeric,jsonb),public.printex_refresh_report_order(uuid),public.printex_refresh_report_queue(integer),
 public.printex_daily_report(date,date),public.printex_report_details(date,date,text,text,integer,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.printex_daily_report(date,date),public.printex_report_details(date,date,text,text,integer,integer,text) TO authenticated;

-- Existing orders and retained histories of deleted orders are reported on first install.
INSERT INTO public.report_refresh_queue(order_id) SELECT id FROM public.orders o
 WHERE NOT EXISTS(SELECT 1 FROM public.report_contributions c WHERE c.order_id=o.id AND c.metric='intake') ON CONFLICT DO NOTHING;
INSERT INTO public.report_refresh_queue(order_id) SELECT DISTINCT order_identity::uuid FROM public.process_history
 WHERE order_identity ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 AND NOT EXISTS(SELECT 1 FROM public.report_contributions c WHERE c.order_id=process_history.order_identity::uuid) ON CONFLICT DO NOTHING;
-- Refresh in the background every minute where pg_cron is available.
DO $$ BEGIN
 IF to_regnamespace('cron') IS NOT NULL THEN
  EXECUTE 'SELECT cron.schedule(''printex-daily-report-refresh'',''* * * * *'',''SELECT public.printex_refresh_report_queue(500);'')';
 END IF;
END $$;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0032_production_capacity.sql
-- Production capacity: machines, working time, standard crew, day overrides of the crew,
-- and machine runs ("Mulai/Selesai cetak"). Safe to rerun.

-- ===== Machines =====
-- Fedar prints Sublim (every non-DTF type), DTF prints DTF, Press presses the Sublim line.
-- Removal is soft so archived orders keep their machine.
DO $$ BEGIN
 IF to_regclass('public.production_machines') IS NULL THEN
  CREATE TABLE public.production_machines (
   id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
   kind text NOT NULL CHECK (kind IN ('fedar','dtf','press')),
   name text NOT NULL CHECK (length(name) BETWEEN 1 AND 40 AND name = btrim(name)),
   created_at timestamptz NOT NULL DEFAULT now(),
   removed_at timestamptz
  );
  -- Seed only on first install: rerunning must not resurrect machines removed later.
  INSERT INTO public.production_machines(kind,name) VALUES ('fedar','Fedar 1'),('fedar','Fedar 2'),('dtf','DTF 1'),('press','Press 1');
 END IF;
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS production_machines_active_name ON public.production_machines(lower(name)) WHERE removed_at IS NULL;
ALTER TABLE public.production_machines ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.production_machines FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.production_machines TO authenticated;
GRANT INSERT(kind,name) ON public.production_machines TO authenticated;
GRANT UPDATE(name,removed_at) ON public.production_machines TO authenticated;
DROP POLICY IF EXISTS production_machines_read ON public.production_machines;
CREATE POLICY production_machines_read ON public.production_machines FOR SELECT TO authenticated USING(public.printex_staff());
DROP POLICY IF EXISTS production_machines_insert ON public.production_machines;
CREATE POLICY production_machines_insert ON public.production_machines FOR INSERT TO authenticated WITH CHECK(public.printex_admin());
DROP POLICY IF EXISTS production_machines_update ON public.production_machines;
CREATE POLICY production_machines_update ON public.production_machines FOR UPDATE TO authenticated USING(public.printex_admin()) WITH CHECK(public.printex_admin());

ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS print_machine_id uuid REFERENCES public.production_machines(id);
CREATE INDEX IF NOT EXISTS orders_print_machine ON public.orders(print_machine_id) WHERE print_machine_id IS NOT NULL;

-- ===== Working time and standard crew (one row) =====
-- Available = shifts x shift_hours; effective (T) = available - break & setup.
-- Standard: 1 shift of 9 hours, 2 hours break & setup (T = 7 hours); crew follows the
-- seeded machines: Fedar 1 per machine (2), DTF 1 per machine (1), Press 3 per machine (3), 1 designer.
CREATE TABLE IF NOT EXISTS public.production_settings (
 singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
 shifts smallint NOT NULL DEFAULT 1 CHECK (shifts BETWEEN 1 AND 3),
 shift_hours numeric(4,2) NOT NULL DEFAULT 9 CHECK (shift_hours > 0 AND shift_hours <= 24),
 planned_downtime_minutes integer NOT NULL DEFAULT 120 CHECK (planned_downtime_minutes BETWEEN 0 AND 1440),
 effective_hours numeric(4,2) NOT NULL DEFAULT 7 CHECK (effective_hours > 0 AND effective_hours <= 24),
 operators_printing smallint NOT NULL DEFAULT 2 CHECK (operators_printing BETWEEN 0 AND 50),
 operators_dtf smallint NOT NULL DEFAULT 1 CHECK (operators_dtf BETWEEN 0 AND 50),
 operators_press smallint NOT NULL DEFAULT 3 CHECK (operators_press BETWEEN 0 AND 50),
 operators_design smallint NOT NULL DEFAULT 1 CHECK (operators_design BETWEEN 0 AND 50),
 -- Design works per order, not per meter (optional): design capacity = orders/hour x T.
 design_orders_per_hour numeric(6,2) CHECK (design_orders_per_hour > 0 AND design_orders_per_hour <= 1000),
 version bigint NOT NULL DEFAULT 1 CHECK (version > 0)
);
CREATE OR REPLACE FUNCTION public.printex_working_hours() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 NEW.effective_hours := round(NEW.shifts*NEW.shift_hours - NEW.planned_downtime_minutes/60.0, 2);
 IF NEW.shifts*NEW.shift_hours > 24 THEN RAISE EXCEPTION 'Jam kerja tersedia maksimal 24 jam per hari'; END IF;
 IF NEW.effective_hours <= 0 THEN RAISE EXCEPTION 'Istirahat & setup harus lebih kecil dari jam kerja tersedia'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS working_hours ON public.production_settings;
CREATE TRIGGER working_hours BEFORE INSERT OR UPDATE ON public.production_settings FOR EACH ROW EXECUTE FUNCTION public.printex_working_hours();
INSERT INTO public.production_settings(singleton) VALUES(true) ON CONFLICT DO NOTHING;
ALTER TABLE public.production_settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.production_settings FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.production_settings TO authenticated;
GRANT UPDATE(shifts,shift_hours,planned_downtime_minutes,operators_printing,operators_dtf,operators_press,operators_design,design_orders_per_hour,version) ON public.production_settings TO authenticated;
DROP POLICY IF EXISTS production_settings_read ON public.production_settings;
CREATE POLICY production_settings_read ON public.production_settings FOR SELECT TO authenticated USING(public.printex_staff());
DROP POLICY IF EXISTS production_settings_write ON public.production_settings;
CREATE POLICY production_settings_write ON public.production_settings FOR UPDATE TO authenticated USING(public.printex_admin()) WITH CHECK(public.printex_admin());

-- ===== Print machine of an order =====
-- Assigns the print machine, optionally moving the order into PRINTING in the same
-- transaction. The move itself reuses printex_mutate_order and all of its role rules.
CREATE OR REPLACE FUNCTION public.printex_set_print_machine(p_order uuid, p_expected_version bigint, p_machine uuid, p_move boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; m public.production_machines; step text; required text;
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=p_order;
 IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;
 SELECT * INTO m FROM public.production_machines WHERE id=p_machine AND removed_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Mesin tidak tersedia'; END IF;
 required := CASE WHEN upper(btrim(o.production_type))='DTF' THEN 'dtf' ELSE 'fedar' END;
 IF m.kind <> required THEN RAISE EXCEPTION 'Order DTF hanya dapat dicetak di mesin DTF; bahan lain di mesin Fedar'; END IF;
 IF p_move THEN
  PERFORM public.printex_mutate_order('move',p_order,p_expected_version,jsonb_build_object('code','PRINTING'));
 ELSIF o.version IS DISTINCT FROM p_expected_version THEN
  RAISE EXCEPTION 'Order telah diubah oleh pengguna lain. Muat ulang lalu coba kembali.' USING ERRCODE='40001';
 END IF;
 SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE;
 SELECT code INTO step FROM public.production_steps WHERE id=o.current_step_id;
 IF step IS DISTINCT FROM 'PRINTING' THEN RAISE EXCEPTION 'Mesin hanya dapat dipilih saat order berada di Proses Sublim'; END IF;
 IF o.print_machine_id IS DISTINCT FROM p_machine THEN UPDATE public.orders SET print_machine_id=p_machine WHERE id=p_order; END IF;
END $$;

-- Per-machine print productivity from saved report contributions (stage time per order).
CREATE OR REPLACE FUNCTION public.printex_machine_productivity(p_start date, p_end date)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
 IF p_start IS NULL OR p_end IS NULL OR p_end < p_start OR p_end - p_start > 366 THEN RAISE EXCEPTION 'Periode tidak valid'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('machineId',x.machine,'dimension',x.dimension,'count',x.n,'meter',x.meter,'milliseconds',x.ms))
  FROM (SELECT o.print_machine_id AS machine,c.dimension,count(*) AS n,sum(c.meter) AS meter,sum(c.milliseconds) AS ms
   FROM public.report_contributions c JOIN public.orders o ON o.id=c.order_id
   WHERE c.metric='productivity' AND (c.dimension LIKE 'sublim:%' OR c.dimension LIKE 'dtf:%')
    AND c.report_date BETWEEN p_start AND p_end AND o.print_machine_id IS NOT NULL
   GROUP BY o.print_machine_id,c.dimension) x),'[]'::jsonb);
END $$;

-- ===== Operator day overrides =====
-- A day that differs from the standard crew (people x hours per person). 0 people is valid.
CREATE TABLE IF NOT EXISTS public.operator_shifts (
 work_date date NOT NULL,
 stage text NOT NULL CHECK (stage IN ('design','printing','press','dtf')),
 people smallint NOT NULL CHECK (people BETWEEN 0 AND 50),
 hours numeric(4,2) NOT NULL CHECK (hours > 0 AND hours <= 24),
 updated_by uuid DEFAULT auth.uid(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY (work_date,stage)
);

-- ===== Machine runs ("Mulai/Selesai cetak") =====
CREATE TABLE IF NOT EXISTS public.print_runs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
 machine_id uuid REFERENCES public.production_machines(id) ON DELETE SET NULL,
 stage text NOT NULL CHECK (stage IN ('printing','press')),
 started_at timestamptz NOT NULL DEFAULT now(),
 ended_at timestamptz CHECK (ended_at >= started_at),
 created_by uuid DEFAULT auth.uid()
);
CREATE UNIQUE INDEX IF NOT EXISTS print_runs_open_order ON public.print_runs(order_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS print_runs_open_machine ON public.print_runs(machine_id) WHERE ended_at IS NULL AND machine_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS print_runs_period ON public.print_runs(started_at);

DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['operator_shifts','print_runs'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated', t);
  EXECUTE format('GRANT SELECT ON public.%I TO authenticated', t);
  EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t||'_read', t);
  -- Writes go through the SECURITY DEFINER functions below.
  EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(public.printex_staff())', t||'_read', t);
 END LOOP;
END $$;

-- Day overrides are set by admins; people NULL returns the day to the standard crew.
CREATE OR REPLACE FUNCTION public.printex_set_operator_shift(p_date date, p_stage text, p_people integer, p_hours numeric)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT public.printex_admin() THEN RAISE EXCEPTION 'Hanya admin yang dapat mengisi jam operator' USING ERRCODE='42501'; END IF;
 IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Tanggal tidak valid'; END IF;
 IF p_people IS NULL THEN
  DELETE FROM public.operator_shifts WHERE work_date=p_date AND stage=p_stage;
  RETURN;
 END IF;
 INSERT INTO public.operator_shifts(work_date,stage,people,hours) VALUES(p_date,p_stage,p_people,p_hours)
 ON CONFLICT (work_date,stage) DO UPDATE SET people=EXCLUDED.people,hours=EXCLUDED.hours,updated_by=auth.uid(),updated_at=now();
END $$;

-- One open run per order and per machine. Press uses the only active press machine.
-- Pressed DTF uses its own press line, which is not measured.
CREATE OR REPLACE FUNCTION public.printex_start_run(p_order uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; step text; run_stage text; machine uuid; busy text; new_id uuid;
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;
 SELECT code INTO step FROM public.production_steps WHERE id=o.current_step_id;
 run_stage := CASE step WHEN 'PRINTING' THEN 'printing' WHEN 'PRESS' THEN 'press' END;
 IF run_stage IS NULL THEN RAISE EXCEPTION 'Mulai cetak hanya untuk order di Proses Sublim atau Proses Press'; END IF;
 IF run_stage='press' AND upper(btrim(o.production_type))='DTF' THEN RAISE EXCEPTION 'Press DTF memakai lini sendiri dan tidak dicatat'; END IF;
 IF EXISTS (SELECT 1 FROM public.print_runs WHERE order_id=p_order AND ended_at IS NULL) THEN RAISE EXCEPTION 'Order ini sedang berjalan'; END IF;
 IF run_stage='printing' THEN
  machine := o.print_machine_id;
  IF machine IS NULL THEN RAISE EXCEPTION 'Pilih mesin print terlebih dahulu'; END IF;
 ELSE
  SELECT CASE WHEN count(*)=1 THEN (array_agg(id))[1] END INTO machine FROM public.production_machines WHERE kind='press' AND removed_at IS NULL;
 END IF;
 IF machine IS NOT NULL THEN
  SELECT x.spk_code INTO busy FROM public.print_runs r JOIN public.orders x ON x.id=r.order_id WHERE r.machine_id=machine AND r.ended_at IS NULL;
  IF busy IS NOT NULL THEN RAISE EXCEPTION 'Mesin masih mengerjakan SPK %. Selesaikan dulu.', busy; END IF;
 END IF;
 INSERT INTO public.print_runs(order_id,machine_id,stage) VALUES(p_order,machine,run_stage) RETURNING id INTO new_id;
 RETURN new_id;
END $$;
CREATE OR REPLACE FUNCTION public.printex_finish_run(p_order uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
 UPDATE public.print_runs SET ended_at=now() WHERE order_id=p_order AND ended_at IS NULL;
END $$;
-- Moving a card to another stage closes a run that was left open.
CREATE OR REPLACE FUNCTION public.printex_close_runs_on_move() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 UPDATE public.print_runs SET ended_at=greatest(started_at,now()) WHERE order_id=NEW.id AND ended_at IS NULL;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS close_runs_on_move ON public.orders;
CREATE TRIGGER close_runs_on_move AFTER UPDATE OF current_step_id ON public.orders
 FOR EACH ROW WHEN (OLD.current_step_id IS DISTINCT FROM NEW.current_step_id) EXECUTE FUNCTION public.printex_close_runs_on_move();

-- Totals of a period (WIB days), clipped to the period and to now.
CREATE OR REPLACE FUNCTION public.printex_efficiency_inputs(p_start date, p_end date)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE ps timestamptz; pe timestamptz;
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum diberi akses oleh admin' USING ERRCODE='42501'; END IF;
 IF p_start IS NULL OR p_end IS NULL OR p_end < p_start OR p_end - p_start > 366 THEN RAISE EXCEPTION 'Periode tidak valid'; END IF;
 ps := p_start::timestamp AT TIME ZONE 'Asia/Jakarta';
 pe := least((p_end + 1)::timestamp AT TIME ZONE 'Asia/Jakarta', now());
 RETURN jsonb_build_object(
  'runs', coalesce((SELECT jsonb_agg(jsonb_build_object('machineId',x.machine_id,'stage',x.stage,'milliseconds',x.ms,'meter',x.meter,'count',x.n)) FROM (
    SELECT r.machine_id,r.stage,
     sum(greatest(0, extract(epoch FROM least(coalesce(r.ended_at,now()),pe) - greatest(r.started_at,ps))) * 1000)::bigint AS ms,
     sum(CASE WHEN r.ended_at >= ps AND r.ended_at < pe THEN o.meter ELSE 0 END) AS meter,
     count(*) FILTER (WHERE r.ended_at >= ps AND r.ended_at < pe) AS n
    FROM public.print_runs r JOIN public.orders o ON o.id=r.order_id
    WHERE r.started_at < pe AND coalesce(r.ended_at,now()) > ps
     AND NOT (r.stage='press' AND upper(btrim(o.production_type))='DTF')
    GROUP BY r.machine_id,r.stage) x),'[]'::jsonb),
  -- Man-hours per working day (a day with production activity or an override):
  -- the day's override, otherwise the standard crew x effective hours.
  'shifts', coalesce((SELECT jsonb_agg(jsonb_build_object('stage',x.stage,'manHours',x.mh,'peopleDays',x.pd)) FROM (
    WITH days AS (
     SELECT DISTINCT (h.occurred_at AT TIME ZONE 'Asia/Jakarta')::date AS d FROM public.process_history h
     WHERE h.occurred_at >= ps AND h.occurred_at < pe
     UNION
     SELECT s.work_date FROM public.operator_shifts s WHERE s.work_date BETWEEN p_start AND p_end
    ), crew AS (
     SELECT st.stage,
      coalesce(s.people,CASE st.stage WHEN 'printing' THEN c.operators_printing WHEN 'dtf' THEN c.operators_dtf WHEN 'press' THEN c.operators_press ELSE c.operators_design END) AS people,
      coalesce(s.hours,c.effective_hours) AS hours
     FROM days dy CROSS JOIN public.production_settings c
     CROSS JOIN (VALUES ('design'),('printing'),('press'),('dtf')) st(stage)
     LEFT JOIN public.operator_shifts s ON s.work_date=dy.d AND s.stage=st.stage
    )
    SELECT stage,sum(people*hours) AS mh,sum(people) AS pd FROM crew WHERE people > 0 GROUP BY stage) x),'[]'::jsonb)
 );
END $$;

REVOKE ALL ON FUNCTION public.printex_working_hours(),public.printex_close_runs_on_move() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f text; BEGIN
 FOREACH f IN ARRAY ARRAY['printex_set_print_machine(uuid,bigint,uuid,boolean)','printex_machine_productivity(date,date)',
  'printex_set_operator_shift(date,text,integer,numeric)','printex_start_run(uuid)','printex_finish_run(uuid)','printex_efficiency_inputs(date,date)'] LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC,anon', f);
  EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO authenticated', f);
 END LOOP;
END $$;

-- Capabilities read by the app at start-up.
CREATE OR REPLACE FUNCTION public.printex_online_status() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT public.printex_staff() THEN RAISE EXCEPTION 'Akun belum aktif. Hubungi admin.' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('schema_version',8,'daily_summaries_enabled',true,'production_capacity_enabled',true,'realtime_tables',
  (SELECT jsonb_agg(tablename) FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public'));
END $$;
NOTIFY pgrst,'reload schema';

-- supabase/migrations/0033_optional_stock_links.sql
-- A stock shortcut may have no link yet (the button then shows "Link belum diatur"). Safe to rerun.
ALTER TABLE public.stock_shortcuts DROP CONSTRAINT IF EXISTS stock_shortcuts_url_check;
ALTER TABLE public.stock_shortcuts ADD CONSTRAINT stock_shortcuts_url_check
 CHECK (url = '' OR (length(url) <= 2048 AND url ~ '^https://[^[:space:]]+$'));

-- supabase/migrations/0034_scheduled_photo_cleanup.sql
-- Scheduled photo cleanup (every 5 minutes, enabled by supabase/jobs/enable-photo-cleanup.sql).
-- Runs with pg_net and Vault; the function is created here and only resolves them when it runs.
-- Credentials are supplied separately to Vault, never embedded in this file. Safe to rerun.
CREATE TABLE IF NOT EXISTS public.photo_cleanup_requests (
  path text PRIMARY KEY,
  request_id bigint NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.photo_cleanup_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.photo_cleanup_requests FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.printex_run_photo_cleanup() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE candidate text; endpoint text; api_key text; encoded text; request bigint; total integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('printex-scheduled-photo-cleanup',16)) THEN RETURN 0; END IF;
  SELECT decrypted_secret INTO endpoint FROM vault.decrypted_secrets WHERE name='printex_storage_url';
  SELECT decrypted_secret INTO api_key FROM vault.decrypted_secrets WHERE name='printex_storage_cleanup_key';
  IF endpoint IS NULL OR api_key IS NULL THEN RAISE EXCEPTION 'Photo cleanup credentials are not configured'; END IF;
  IF endpoint !~ '^https://[a-z0-9]+\.supabase\.co$' THEN RAISE EXCEPTION 'Invalid Storage endpoint'; END IF;

  DELETE FROM public.order_photo_cleanup q WHERE q.queued_at < now()-interval '1 day'
    AND NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='order-photos' AND s.name=q.path);
  DELETE FROM public.photo_cleanup_requests r WHERE r.requested_at < now()-interval '7 days'
    AND NOT EXISTS(SELECT 1 FROM storage.objects s WHERE s.bucket_id='order-photos' AND s.name=r.path);

  FOR candidate IN
    SELECT s.name FROM storage.objects s
    LEFT JOIN public.photo_cleanup_requests r ON r.path=s.name
    WHERE s.bucket_id='order-photos'
      AND (s.created_at < now()-interval '24 hours' OR EXISTS(SELECT 1 FROM public.order_photo_cleanup q WHERE q.path=s.name))
      AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=s.name)
      AND (r.requested_at IS NULL OR r.requested_at < now()-interval '4 minutes')
    ORDER BY r.requested_at NULLS FIRST,s.created_at,s.name LIMIT 50
  LOOP
    -- Same lock and persistent claim used by the photo-link RPC.
    PERFORM pg_advisory_xact_lock(hashtextextended(candidate,16));
    IF NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.photo_path=candidate) THEN
      INSERT INTO public.order_photo_cleanup AS q(path,claimed) VALUES(candidate,true)
      ON CONFLICT(path) DO UPDATE SET claimed=true;
      -- Percent-encode UTF-8 bytes while preserving folder separators.
      SELECT string_agg(CASE WHEN chr(b) ~ '^[A-Za-z0-9_~/.-]$' THEN chr(b)
        ELSE '%'||upper(lpad(to_hex(b),2,'0')) END,'' ORDER BY n)
      INTO encoded FROM (SELECT n,get_byte(convert_to(candidate,'UTF8'),n) AS b
        FROM generate_series(0,octet_length(convert_to(candidate,'UTF8'))-1) n) bytes;
      request := net.http_delete(
        url := endpoint||'/storage/v1/object/order-photos/'||encoded,
        headers := jsonb_build_object('apikey',api_key), timeout_milliseconds := 10000);
      INSERT INTO public.photo_cleanup_requests(path,request_id) VALUES(candidate,request)
      ON CONFLICT(path) DO UPDATE SET request_id=EXCLUDED.request_id,requested_at=now();
      total := total+1;
    END IF;
  END LOOP;
  -- pg_net dispatches after commit, so claims survive lost HTTP responses.
  -- Failed removals remain eligible for the next run; never DELETE storage metadata.
  RETURN total;
END $$;
REVOKE ALL ON FUNCTION public.printex_run_photo_cleanup() FROM PUBLIC,anon,authenticated;

COMMIT;
